const J = (o, s = 200) => new Response(JSON.stringify(o), { status: s, headers: { 'content-type': 'application/json' } });
const enc = new TextEncoder();
const b64 = (b) => btoa(String.fromCharCode(...new Uint8Array(b))).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
const ub64 = (s) => Uint8Array.from(atob(s.replace(/-/g, '+').replace(/_/g, '/')), (c) => c.charCodeAt(0));
function withFirst(reader, first) { let used = false; return { read: async () => { if (!used) { used = true; return first; } return reader.read(); }, cancel: () => reader.cancel() }; }
const isPro = (rec) => !!(rec && rec.proUntil && rec.proUntil > Date.now());
